import React, { useState } from 'react';
import API from '../api/axiosClient';
import { useQuery, useMutation } from '@tanstack/react-query';
import { loadStripe } from '@stripe/stripe-js';
import { Elements, CardElement, useStripe, useElements } from '@stripe/react-stripe-js';
import { FaWallet, FaHistory, FaCreditCard, FaPlusCircle } from 'react-icons/fa';

const stripePromise = loadStripe('pk_test_your_publishable_stripe_key');

function TopUpForm({ orgId, onSuccess }) {
    const stripe = useStripe();
    const elements = useElements();
    const [amount, setAmount] = useState('');
    const [loading, setLoading] = useState(false);
    const [message, setMessage] = useState('');

    const handleTopUp = async (e) => {
        e.preventDefault();
        if (!stripe || !elements || !amount) return;

        setLoading(true);
        setMessage('');

        try {
            // 1. Create Payment Intent on Backend
            const { data } = await API.post(`/payment/${orgId}/topup-intent`, { amount: parseFloat(amount) });
            const { clientSecret } = data;

            // 2. Confirm Card Payment with Stripe
            const result = await stripe.confirmCardPayment(clientSecret, {
                payment_method: {
                    card: elements.getElement(CardElement),
                }
            });

            if (result.error) {
                setMessage(result.error.message);
            } else if (result.paymentIntent.status === 'succeeded') {
                setMessage('Top-up successful! Balance updated.');
                setAmount('');
                elements.getElement(CardElement).clear();
                onSuccess();
            }
        } catch (err) {
            setMessage(err.response?.data?.error || 'Payment failed');
        } finally {
            setLoading(false);
        }
    };

    return (
        <form onSubmit={handleTopUp} className="bg-gray-800 p-6 rounded-xl border border-gray-700">
            <h3 className="text-xl font-semibold mb-4 flex items-center gap-2">
                <FaCreditCard className="text-indigo-400" /> Self-Service Card Top-Up
            </h3>
            <div className="mb-4">
                <label className="block text-sm text-gray-400 mb-2">Amount ($)</label>
                <input 
                    type="number" 
                    min="1" 
                    value={amount} 
                    onChange={(e) => setAmount(e.target.value)}
                    placeholder="20.00" 
                    className="w-full p-3 bg-gray-900 border border-gray-700 rounded-lg focus:outline-none focus:border-indigo-500 text-white"
                    required
                />
            </div>
            <div className="mb-4 p-3 bg-gray-900 border border-gray-700 rounded-lg">
                <CardElement options={{ style: { base: { color: '#ffffff', '::placeholder': { color: '#9ca3af' } } } }} />
            </div>
            {message && <p className="mb-4 text-sm text-indigo-300">{message}</p>}
            <button 
                type="submit" 
                disabled={!stripe || loading}
                className="w-full bg-emerald-600 hover:bg-emerald-500 p-3 rounded-lg font-semibold transition disabled:opacity-50"
            >
                {loading ? 'Processing...' : 'Fund Account'}
            </button>
        </form>
    );
}

export default function CustomerDashboard({ orgId }) {
    // Fetch Customer Profile & Balance using TanStack Query
    const { data: profile, refetch } = useQuery({
        queryKey: ['customerProfile', orgId],
        queryFn: async () => {
            const res = await API.get(`/auth/${orgId}/me`);
            return res.data;
        }
    });

    return (
        <div className="min-h-screen bg-gray-900 text-white p-8">
            <h1 className="text-3xl font-bold mb-6 flex items-center gap-2">
                <FaWallet className="text-emerald-400" /> Customer Loyalty Portal
            </h1>

            <div className="grid grid-cols-1 md:grid-cols-3 gap-8 mb-8">
                {/* Balance Card */}
                <div className="bg-gray-800 p-6 rounded-xl border border-gray-700">
                    <p className="text-gray-400 text-sm">Available Balance</p>
                    <h2 className="text-4xl font-extrabold text-emerald-400 mt-2">
                        ${profile?.balance?.toFixed(2) || '0.00'}
                    </h2>
                </div>

                {/* Linked RFID Card */}
                <div className="bg-gray-800 p-6 rounded-xl border border-gray-700 md:col-span-2 flex items-center justify-between">
                    <div>
                        <p className="text-gray-400 text-sm">Linked RFID Card UID</p>
                        <h3 className="text-xl font-mono font-bold mt-1 text-indigo-300">
                            {profile?.rfidUid || 'Unlinked (Contact Worker)'}
                        </h3>
                    </div>
                    <span className="px-3 py-1 bg-indigo-900 text-indigo-200 text-xs font-semibold rounded-full border border-indigo-700">
                        Secure UID
                    </span>
                </div>
            </div>

            {/* Top-Up Section Wrapped in Stripe Elements */}
            <Elements stripe={stripePromise}>
                <TopUpForm orgId={orgId} onSuccess={refetch} />
            </Elements>
        </div>
    );
}
